using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Task<CapturedRequest> captured;
    private HttpStatusCode statusCode = HttpStatusCode.OK;
    private string responseBody = """{"status":"approved"}""";

    private sealed record CapturedRequest(string Method, string Path, string? ContentType, string Body);

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        var prefix = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(prefix);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(prefix) };
        captured = Serve();
    }

    private async Task<CapturedRequest> Serve()
    {
        var context = await listener.GetContextAsync();
        using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
        var body = await reader.ReadToEndAsync();
        var request = new CapturedRequest(context.Request.HttpMethod, context.Request.Url!.AbsolutePath, context.Request.ContentType, body);

        var bytes = Encoding.UTF8.GetBytes(responseBody);
        context.Response.StatusCode = (int)statusCode;
        context.Response.ContentType = "application/json";
        context.Response.ContentLength64 = bytes.Length;
        await context.Response.OutputStream.WriteAsync(bytes);
        context.Response.Close();
        return request;
    }

    private static int FreePort()
    {
        var tcp = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        tcp.Start();
        var port = ((IPEndPoint)tcp.LocalEndpoint).Port;
        tcp.Stop();
        return port;
    }

    private Task<AuthorizationOutcome> Authorize(string reference = "ORD-1", decimal amount = 12.5m, string currency = "eur") =>
        new HttpPaymentGateway(client).AuthorizeAsync(reference, new Money(amount, currency), CancellationToken.None);

    [Fact]
    public async Task The_request_is_a_JSON_POST_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        await Authorize("ORD-42", 19.99m, "eur");

        var request = await captured;
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);

        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-42", root.GetProperty("reference").GetString());
        Assert.Equal(19.99m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        responseBody = """{"status":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        responseBody = """{"status":"declined"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        responseBody = """{"id":"abc","status":"approved","risk":{"score":3}}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_read_as_declined_even_if_the_body_claims_approval()
    {
        statusCode = HttpStatusCode.PaymentRequired;
        responseBody = """{"status":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_an_empty_body_is_read_as_declined()
    {
        statusCode = HttpStatusCode.PaymentRequired;
        responseBody = "";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.UnprocessableEntity)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_failure_statuses_surface_as_errors_and_are_never_treated_as_approval(HttpStatusCode status)
    {
        statusCode = status;
        responseBody = """{"status":"approved"}""";

        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize());
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_exactly_approved_is_never_treated_as_approval(string body)
    {
        responseBody = body;

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_body_that_is_not_JSON_fails_instead_of_approving()
    {
        responseBody = "<html>oops</html>";

        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize());
    }

    public void Dispose()
    {
        listener.Close();
        client.Dispose();
    }
}
